import {ListView} from '@github-ui/list-view'
import {ListViewMetadata} from '@github-ui/list-view/ListViewMetadata'
import {ListItem} from '@github-ui/list-view/ListItem'
import {ListItemTitle} from '@github-ui/list-view/ListItemTitle'
import {ListItemDescription} from '@github-ui/list-view/ListItemDescription'
import {ListItemMainContent} from '@github-ui/list-view/ListItemMainContent'
import {ListItemActionBar} from '@github-ui/list-view/ListItemActionBar'
import {ActionList, Tooltip, Button, Banner} from '@primer/react'
import {BookIcon, CommentAiIcon, TrashIcon} from '@primer/octicons-react'
import type {Memory} from '../types/memory'
import {indexRoute, deleteRoute} from '../routes/memory-route'
import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {useRouteParams} from '@github-ui/react-core/future/use-route-params'
import {reactFetch} from '@github-ui/verified-fetch'
import type React from 'react'
import {useState} from 'react'
import {useMutation, useQueryClient} from '@github-ui/react-query'
import {Blankslate} from '@primer/react/experimental'

const SourceAgents = {
  ccr: 'Copilot Code Review',
  cca: 'Copilot Coding Agent',
}

interface DeleteResult {
  deletedIds: string[]
  notDeletedIds: string[]
}

async function deleteMemories(owner: string, name: string, ids: string[]): Promise<DeleteResult> {
  const path = deleteRoute.generatePath({owner, name})
  const data = new FormData()
  for (const id of ids) {
    data.append('ids[]', id)
  }
  const response = await reactFetch(path, {
    method: 'delete',
    body: data,
  })

  // 204 No Content means all deletions succeeded
  if (response.status === 204) {
    return {deletedIds: ids, notDeletedIds: []}
  }

  // 200 OK with body means partial success
  if (response.ok) {
    const body = await response.json()
    return {
      deletedIds: body.deleted_ids ?? [],
      notDeletedIds: body.not_deleted_ids ?? [],
    }
  }

  // Any other non-ok response is a complete failure
  throw new Error(`Failed to delete memory: ${response.statusText}`)
}

type MemoryListItemProps = {
  memory: Memory
  onDelete: (id: string) => void
  isSelected: boolean
  onSelect: (isSelected: boolean) => void
}

interface CitationLocation {
  startLine: number
  endLine: number
}

interface Citation {
  path: string
  locations: CitationLocation[]
}

const parseCitation = (citation: string): Citation[] => {
  const citations: string[] = citation.split(';').map(c => c.trim())
  return citations.map(cit => {
    const [path, locationSpecs] = cit.split(':')
    if (!path) {
      return {path: '', locations: []}
    }
    const locations: CitationLocation[] = []
    if (!locationSpecs) {
      return {path, locations}
    }
    for (const locSpec of locationSpecs.split(',')) {
      const [startStr, endStr] = locSpec.split('-')
      if (!startStr) continue
      const startLine = parseInt(startStr, 10)
      const endLine = endStr ? parseInt(endStr, 10) : startLine
      locations.push({startLine, endLine})
    }

    return {path, locations}
  })
}

function Citation({citation}: {citation: string}) {
  const citations = parseCitation(citation)

  return citations.map(cit => (
    <ListItemDescription key={cit.path}>
      <span>
        <BookIcon />
        {cit.path}
      </span>
    </ListItemDescription>
  ))
}

function MemoryListItem({memory, onDelete, isSelected, onSelect}: MemoryListItemProps) {
  const handleDelete = (e: React.MouseEvent | React.KeyboardEvent) => {
    e.preventDefault()
    onDelete(memory.id)
  }

  return (
    <ListItem
      isSelected={isSelected}
      onSelect={onSelect}
      title={<ListItemTitle headingStyle={{minWidth: 0}} value={memory.fact} />}
      secondaryActions={
        <ListItemActionBar
          label="memory actions"
          actions={[
            {
              key: 'delete-memory',
              render: isOverflowMenu => {
                return isOverflowMenu ? (
                  <ActionList.Item onSelect={handleDelete}>
                    <ActionList.LeadingVisual>
                      <Button variant="invisible" size="small" aria-label="Delete memory" onClick={handleDelete}>
                        <TrashIcon />
                      </Button>
                    </ActionList.LeadingVisual>
                    Delete memory
                  </ActionList.Item>
                ) : (
                  <Button variant="invisible" size="small" aria-label="Delete memory" onClick={handleDelete}>
                    <TrashIcon />
                  </Button>
                )
              },
            },
          ]}
        />
      }
    >
      <ListItemMainContent>
        <ListItemDescription>
          <span className="color-fg-muted">{memory.subject}</span>
          {memory.source?.agent && (
            <Tooltip
              text={`Source Agent: ${
                memory.source.agent in SourceAgents
                  ? SourceAgents[memory.source.agent as keyof typeof SourceAgents]
                  : memory.source.agent
              }`}
            >
              <span className="color-fg-muted ml-2">
                {memory.source.agent in SourceAgents
                  ? SourceAgents[memory.source.agent as keyof typeof SourceAgents]
                  : memory.source.agent}
              </span>
            </Tooltip>
          )}
        </ListItemDescription>
      </ListItemMainContent>
    </ListItem>
  )
}

export function Memory() {
  const payload = useRouteQuery(indexRoute, 'mainQuery')
  const memories = payload?.data.memories ?? []

  const {owner, name} = useRouteParams(indexRoute)

  // We want to update the index route payload after deletion(s).
  // Since the route is not mounted we will construct a partial query key.
  // See https://thehub.github.com/epd/engineering/dev-practicals/frontend/react/data-router/recipes/mutations/

  // Full query key for the current page's data — used to refetch the exact query backing this view.
  const currentPageQueryKey = payload.queryKey

  // Partial (prefix) query key for the index route — invalidates all cached variants
  // of the memories list (e.g. different pagination params) so stale data isn't shown
  // when navigating back.
  const indexRoutePartialQueryKey = indexRoute.queries.mainQuery.makeQueryKey()

  const queryClient = useQueryClient()
  const [deleteResult, setDeleteResult] = useState<DeleteResult | null>(null)

  const deleteMemoryMutation = useMutation({
    mutationFn: (ids: string[]) => deleteMemories(owner, name, ids),
    onSuccess: (result: DeleteResult) => {
      // Track partial success for UI feedback
      if (result.notDeletedIds.length > 0) {
        setDeleteResult(result)
      } else {
        setDeleteResult(null)
      }
      // Invalidate the index route query to refetch the updated list of memories
      queryClient.invalidateQueries({queryKey: currentPageQueryKey})
      queryClient.invalidateQueries({queryKey: indexRoutePartialQueryKey})
    },
    onError: () => {
      // Clear any previous partial success result on full failure
      setDeleteResult(null)
    },
  })

  const handleDeleteMemory = (id: string) => {
    setDeleteResult(null)
    deleteMemoryMutation.mutate([id])
  }
  const [selectedIds, setSelectedIds] = useState<Set<string>>(() => new Set())

  const handleItemSelect = (id: string) => (selected: boolean) => {
    setSelectedIds(prev => {
      const next = new Set(prev)
      if (selected) next.add(id)
      else next.delete(id)
      return next
    })
  }

  const handleToggleSelectAll = (isAllSelected: boolean) => {
    if (isAllSelected) {
      setSelectedIds(new Set(memories.map(m => m.id)))
    } else {
      setSelectedIds(new Set())
    }
  }

  const handleDeleteMemories = async () => {
    if (selectedIds.size === 0) return
    setDeleteResult(null)
    const ids = Array.from(selectedIds)
    const result = await deleteMemoryMutation.mutateAsync(ids)
    // Only clear successfully deleted items from selection
    if (result.deletedIds.length > 0) {
      setSelectedIds(prev => {
        const next = new Set(prev)
        for (const id of result.deletedIds) {
          next.delete(id)
        }
        return next
      })
    }
  }

  return (
    <div>
      <div className="d-flex flex-items-center flex-justify-between gap-2 width-full border-bottom pb-2 tmp-mb-3">
        <h2 className="Subhead-heading Subhead-heading--large">Copilot memory</h2>
      </div>
      {deleteMemoryMutation.isError && (
        <Banner variant="critical" title="Error" hideTitle description="Failed to delete memories. Please try again." />
      )}
      {deleteResult && deleteResult.notDeletedIds.length > 0 && (
        <Banner
          variant="warning"
          title="Partial deletion"
          hideTitle
          description={`Successfully deleted ${deleteResult.deletedIds.length} ${deleteResult.deletedIds.length === 1 ? 'memory' : 'memories'}, but ${deleteResult.notDeletedIds.length} ${deleteResult.notDeletedIds.length === 1 ? 'memory' : 'memories'} could not be deleted.`}
          onDismiss={() => setDeleteResult(null)}
        />
      )}
      <ListView
        title="List of memories"
        isSelectable
        className="border rounded-2"
        metadata={
          memories.length > 0 ? (
            <ListViewMetadata
              title={`${memories.length} ${memories.length === 1 ? 'memory' : 'memories'}`}
              onToggleSelectAll={handleToggleSelectAll}
            >
              {selectedIds.size > 0 && (
                <Button
                  leadingVisual={TrashIcon}
                  variant="danger"
                  onClick={handleDeleteMemories}
                  aria-label="Delete selected memories"
                >
                  Delete
                </Button>
              )}
            </ListViewMetadata>
          ) : undefined
        }
        totalCount={memories.length}
      >
        {memories.length > 0 ? (
          memories.map(m => (
            <MemoryListItem
              key={m.id}
              memory={m}
              onDelete={handleDeleteMemory}
              isSelected={selectedIds.has(m.id)}
              onSelect={handleItemSelect(m.id)}
            />
          ))
        ) : (
          <Blankslate>
            <Blankslate.Visual>
              <CommentAiIcon size="medium" />
            </Blankslate.Visual>
            <Blankslate.Heading>No memories found</Blankslate.Heading>
            <Blankslate.Description>
              This repository has no memories or you have insufficient access to manage them.
            </Blankslate.Description>
          </Blankslate>
        )}
      </ListView>
    </div>
  )
}
